import { describe, expect, it } from "vitest";
import { roundCents } from "../src/billing/round";

describe("roundCents", () => {
  it("sends half-cent ties to the even cent so invoices aren't biased upward", () => {
    expect(roundCents(102.5)).toBe(102);
    expect(roundCents(103.5)).toBe(104);
    expect(roundCents(-102.5)).toBe(-102);
    expect(roundCents(-103.5)).toBe(-104);
  });

  it("rounds non-tie amounts to the nearest cent", () => {
    expect(roundCents(102.49)).toBe(102);
    expect(roundCents(102.51)).toBe(103);
    expect(roundCents(-102.51)).toBe(-103);
    expect(roundCents(250)).toBe(250);
  });
});

